/* BONES WALKING, eight ways. Same five-sheet-plus-mirror trick as PKDIRS (the run set) and the
   same anchor rule, but these are 25-frame cycles rather than 8 and each direction was rendered
   at its own distance from the camera - tail-on came out nearly half size, which is why he
   shrank every time he walked away. The correction is measured against the run set direction by
   direction and BAKED INTO THE STORED PIXELS (see mkwalk.py), so every strip here is already at
   one body scale and nothing needs a draw-time multiplier. `n` is the cycle length. */
const PKWALK={
  S:{w:33,h:88,n:25,sc:1,ax:0.5206,src:"data:image/png;base64,"},
  SE:{w:89,h:78,n:25,sc:1,ax:0.5605,src:"data:image/png;base64,"},
  E:{w:95,h:65,n:25,sc:1,ax:0.5243,src:"data:image/png;base64,"},
  NE:{w:78,h:74,n:25,sc:1,ax:0.5158,src:"data:image/png;base64,"},
  N:{w:31,h:73,n:25,sc:1,ax:0.4924,src:"data:image/png;base64,"},
};
const PKWALKIMG={};
for(const k in PKWALK){ const i=new Image(); i.src=PKWALK[k].src; PKWALKIMG[k]=i; }
